-- Contenu servi depuis Supabase plutôt que figé dans le bundle.
--
-- Corriger une attribution ou ajouter dix citations demandait jusqu'ici une soumission
-- App Store complète, review comprise. La table ci-dessous devient la source de vérité ;
-- `Shared/Content/content.json` reste embarqué et sert de secours au premier lancement et
-- hors ligne (voir `ContentStore.loadQuotes`).
--
-- `context`, `source` et `year` sont nuls partout au départ : ce sont des faits à
-- vérifier un par un, pas quelque chose qui se génère. L'app les affiche quand ils
-- existent et se tait quand ils manquent.

create table if not exists public.quotes (
  id text primary key,
  text text not null,
  author text not null,
  category text not null,
  context text,
  source text,
  year integer,
  updated_at timestamptz not null default now()
);

alter table public.quotes enable row level security;

-- Lecture pour tout compte connecté, écriture pour personne : le contenu se modifie
-- depuis le SQL Editor ou avec `service_role`, jamais depuis l'app.
drop policy if exists "read quotes" on public.quotes;
create policy "read quotes" on public.quotes
  for select
  to authenticated
  using (true);

revoke insert, update, delete on public.quotes from authenticated, anon;

create index if not exists quotes_category_idx on public.quotes (category);

-- Amorçage depuis le contenu embarqué. `on conflict do nothing` : rejouer la migration ne
-- doit jamais écraser une correction faite depuis.

on conflict (id) do nothing;
