insert into public.quotes (id, text, author, category) values
  ('q-0005', 'Quand vous êtes dans le sens contraire du courant et que vous nagez vite, vous reculez moins que les autres.', 'Bernard Tapie', 'mindset'),
  ('q-0006', 'La réussite, c''est un peu de talent, beaucoup de travail et surtout une passion dévorante.', 'Bernard Tapie', 'mindset'),
  ('q-0007', 'Seul un poisson mort navigue dans le sens du courant.', 'Bernard Arnault', 'mindset'),
  ('q-0008', 'Un bon produit peut durer éternellement.', 'Bernard Arnault', 'mindset'),
  ('q-0009', 'Si vous contrôlez votre distribution, vous contrôlez votre image.', 'Bernard Arnault', 'leadership'),
  ('q-0011', 'La seule façon de faire du bon travail est d''aimer ce que vous faites.', 'Steve Jobs', 'mindset'),
  ('q-0012', 'L''innovation distingue un leader d''un suiveur.', 'Steve Jobs', 'leadership'),
  ('q-0013', 'Votre temps est limité, ne le gaspillez pas en vivant la vie de quelqu''un d''autre.', 'Steve Jobs', 'mindset'),
  ('q-0014', 'Qu''est-ce qu''une entreprise ? C''est simplement une idée qui améliore la vie de quelqu''un d''autre.', 'Richard Branson', 'leadership'),
  ('q-0015', 'Écoutez plus que vous parlez. Personne n''a rien appris en s''entendant parler.', 'Richard Branson', 'leadership'),
  ('q-0016', 'Seul un imbécile ne change jamais d''avis.', 'Richard Branson', 'mindset'),
  ('q-0017', 'L''opportunité se situe à l''endroit où se trouvent les réclamations et les plaintes.', 'Jack Ma', 'mindset'),
  ('q-0019', 'L''échec est simplement l''opportunité de recommencer, cette fois de manière plus pertinente.', 'Henry Ford', 'mindset'),
  ('q-0020', 'Prenez mes idées, j''en aurai d''autres.', 'Coco Chanel', 'mindset'),
  ('q-0021', 'Prudence n''est que l''euphémisme de peur.', 'Jules Renard', 'mindset'),
  ('q-0022', 'La peur bloque la compréhension intelligente de la vie.', 'Jiddu Krishnamurti', 'mindset'),
  ('q-0023', 'J''ai appris que le courage n''est pas l''absence de peur, mais la capacité de la vaincre.', 'Nelson Mandela', 'mindset'),
  ('q-0025', 'Le seul endroit où le succès vient avant le travail, c''est dans le dictionnaire.', 'Vidal Sassoon', 'mindset'),
  ('q-0026', 'Les gagnants trouvent des moyens, les perdants des excuses.', 'Franklin D. Roosevelt', 'mindset'),
  ('q-0028', 'L''audace réussit à ceux qui savent profiter des occasions.', 'Marcel Proust', 'mindset'),
  ('q-0029', 'Un pessimiste voit la difficulté dans chaque opportunité. Un optimiste voit une opportunité dans chaque difficulté.', 'Winston Churchill', 'mindset'),
  ('q-0030', 'Ne cherchez pas d''ascenseur, il n''y en a pas : les entrepreneurs prennent toujours l''escalier !', 'Frédéric Mazzella', 'mindset'),
  ('q-0032', 'Le capitalisme est un pari sur le mouvement : c''est de là que vient le progrès.', 'Alain Minc', 'finance'),
  ('q-0033', 'La victoire appartient à celui qui a la persévérance la plus longue.', 'Napoléon Bonaparte', 'mindset'),
  ('q-0034', 'Toutes les choses semblent réalisables par la volonté et le courage.', 'Napoléon Bonaparte', 'mindset'),
  ('q-0035', 'Se concentrer sur le client rend une entreprise plus résiliente.', 'Jeff Bezos', 'sales'),
  ('q-0037', 'Votre marque est ce que les gens disent de vous lorsque vous n''êtes pas dans la pièce.', 'Jeff Bezos', 'sales'),
  ('q-0038', 'Si vous ne voulez jamais être critiqué, ne faites rien de nouveau.', 'Jeff Bezos', 'mindset'),
  ('q-0039', 'Observez les clients, pas les concurrents.', 'Jeff Bezos', 'sales'),
  ('q-0040', 'Si vous voulez être inventif, vous devez être prêt à échouer.', 'Jeff Bezos', 'mindset'),
  ('q-0041', 'L''échec fait partie intégrante de l''invention.', 'Jeff Bezos', 'mindset'),
  ('q-0042', 'Nous sommes têtus sur la vision. Nous sommes flexibles sur les détails.', 'Jeff Bezos', 'leadership'),
  ('q-0043', 'L''échec est une option. Si les choses n''échouent pas, vous n''innovez pas assez.', 'Elon Musk', 'mindset'),
  ('q-0044', 'La persévérance est très importante. N''abandonnez jamais à moins d''y être obligé.', 'Elon Musk', 'mindset'),
  ('q-0045', 'Beaucoup de choses sont improbables, seules quelques-unes sont impossibles.', 'Elon Musk', 'mindset'),
  ('q-0046', 'Si les règles vous empêchent de progresser, battez-vous pour les changer.', 'Elon Musk', 'mindset'),
  ('q-0047', 'Vous devez être assez motivé pour y arriver. Sinon, vous vous rendrez simplement misérable.', 'Elon Musk', 'mindset'),
  ('q-0048', 'Lorsque quelque chose est suffisamment importante, vous la faites même si les chances ne sont pas en votre faveur.', 'Elon Musk', 'mindset'),
  ('q-0050', 'Se réunir est un début ; rester ensemble est un progrès ; travailler ensemble est la réussite.', 'Henry Ford', 'leadership'),
  ('q-0051', 'Quand tout semble être contre vous, souvenez-vous que l''avion décolle face au vent.', 'Henry Ford', 'mindset'),
  ('q-0052', 'Ce n''est pas l''employeur qui paie les salaires, mais le client.', 'Henry Ford', 'sales'),
  ('q-0053', 'Les deux choses les plus importantes n''apparaissent pas au bilan : sa réputation et ses hommes.', 'Henry Ford', 'leadership'),
  ('q-0054', 'La qualité signifie faire les choses correctement quand personne ne regarde.', 'Henry Ford', 'mindset'),
  ('q-0055', 'Les obstacles sont ces choses effrayantes que vous voyez quand vous détournez les yeux de votre objectif.', 'Henry Ford', 'mindset'),
  ('q-0057', 'Il faut 20 ans pour bâtir une réputation et cinq minutes pour l''anéantir.', 'Warren Buffett', 'finance'),
  ('q-0058', 'Le risque provient de ne pas savoir ce que l''on fait.', 'Warren Buffett', 'finance'),
  ('q-0059', 'Achetez seulement des choses que vous seriez parfaitement heureux de posséder si le marché s''effondrait pendant dix ans.', 'Warren Buffett', 'finance'),
  ('q-0060', 'Notre horizon d''investissement préféré est : pour toujours.', 'Warren Buffett', 'finance'),
  ('q-0061', 'La bourse est un moyen de transférer l''argent des impatients vers les patients.', 'Warren Buffett', 'finance'),
  ('q-0062', 'Le meilleur investissement que vous puissiez faire, c''est de miser sur vos propres capacités.', 'Warren Buffett', 'finance'),
  ('q-0063', 'Tous nos rêves peuvent devenir réalité si nous avons le courage de les poursuivre.', 'Walt Disney', 'mindset'),
  ('q-0065', 'La manière de commencer est d''arrêter de parler et de commencer à faire.', 'Walt Disney', 'mindset'),
  ('q-0068', 'Ce n''est pas votre faute si vous êtes né pauvre. En revanche, si vous mourez pauvre, c''est votre erreur.', 'Bill Gates', 'finance'),
  ('q-0069', 'La patience est un élément clé de la réussite.', 'Bill Gates', 'mindset'),
  ('q-0070', 'Le succès est un mauvais professeur. Il pousse les gens intelligents à croire qu''ils sont infaillibles.', 'Bill Gates', 'mindset'),
  ('q-0071', 'Il ne faut jamais se comparer aux autres. Le faire, c''est s''insulter soi-même.', 'Bill Gates', 'mindset'),
  ('q-0072', 'Pour gagner gros, il faut parfois prendre de gros risques.', 'Bill Gates', 'finance'),
  ('q-0073', 'Célébrer le succès, c''est bien, mais il est plus important de tirer les leçons de l''échec.', 'Bill Gates', 'mindset'),
  ('q-0074', 'Le plus grand risque est de ne prendre aucun risque.', 'Mark Zuckerberg', 'mindset'),
  ('q-0075', 'Si les choses ne se cassent pas, vous ne vous déplacez pas assez vite.', 'Mark Zuckerberg', 'mindset'),
  ('q-0076', 'La chose la plus importante est de garder votre équipe aussi petite que possible.', 'Mark Zuckerberg', 'leadership'),
  ('q-0077', 'Mon objectif n''a jamais été de créer une entreprise, mais de bâtir quelque chose susceptible de changer le monde.', 'Mark Zuckerberg', 'leadership'),
  ('q-0079', 'L''échec est un excellent enseignant et chaque erreur a une leçon à offrir.', 'Oprah Winfrey', 'mindset'),
  ('q-0080', 'Entourez-vous seulement de personnes qui vont vous élever plus haut.', 'Oprah Winfrey', 'mindset'),
  ('q-0081', 'Vous ne devenez pas ce que vous voulez, vous devenez ce que vous croyez.', 'Oprah Winfrey', 'mindset'),
  ('q-0085', 'Celui qui n''a pas d''objectifs ne risque pas de les atteindre.', 'Sun Tzu', 'mindset'),
  ('q-0086', 'Le bon général a gagné la bataille avant de l''engager.', 'Sun Tzu', 'leadership'),
  ('q-0087', 'Un grand dirigeant commande par l''exemple et non par la force.', 'Sun Tzu', 'leadership'),
  ('q-0088', 'Connais l''adversaire et surtout connais-toi toi-même et tu seras invincible.', 'Sun Tzu', 'mindset'),
  ('q-0089', 'Le commencement est beaucoup plus que la moitié de l''objectif.', 'Aristote', 'mindset'),
  ('q-0090', 'C''est par l''expérience que la science et l''art font leur progrès.', 'Aristote', 'mindset'),
  ('q-0092', 'Le courage est la première des qualités humaines car elle garantit toutes les autres.', 'Aristote', 'mindset'),
  ('q-0094', 'Faites le premier pas sur le chemin de la foi. Vous n''avez pas à le parcourir entièrement, juste à faire le premier pas.', 'Martin Luther King', 'mindset'),
  ('q-0095', 'Avoir la foi, c''est monter la première marche, même quand on ne voit pas tout l''escalier.', 'Martin Luther King', 'mindset'),
  ('q-0097', 'Tout ce que tu feras sera dérisoire, mais il est essentiel que tu le fasses.', 'Mahatma Gandhi', 'mindset'),
  ('q-0098', 'Je ne crains pas l''homme qui a pratiqué 10 000 coups une fois, mais celui qui a pratiqué un coup 10 000 fois.', 'Bruce Lee', 'mindset'),
  ('q-0099', 'Connaître ne suffit pas, il faut savoir appliquer. La volonté ne suffit pas, il faut savoir agir.', 'Bruce Lee', 'mindset'),
  ('q-0100', 'Ne crains pas l''échec. Ce n''est pas l''échec, mais le manque d''ambition qui est un crime.', 'Bruce Lee', 'mindset'),
  ('q-0101', 'Il n''y a pas de limites. Il y a seulement des niveaux, et tu ne dois pas en rester là.', 'Bruce Lee', 'mindset'),
  ('q-0102', 'C''est dur d''échouer, mais c''est pire de n''avoir jamais essayé de réussir.', 'Theodore Roosevelt', 'mindset'),
  ('q-0103', 'Le seul homme à ne jamais faire d''erreurs est celui qui ne fait rien.', 'Theodore Roosevelt', 'mindset'),
  ('q-0105', 'Parlez doucement, et tenez un gros bâton, vous irez loin.', 'Theodore Roosevelt', 'leadership'),
  ('q-0106', 'N''ayez pas peur d''échouer. Ayez peur de ne pas essayer.', 'Michael Jordan', 'mindset'),
  ('q-0107', 'Je peux accepter l''échec, tout le monde échoue dans quelque chose. Mais je ne peux pas accepter de ne pas essayer.', 'Michael Jordan', 'mindset'),
  ('q-0108', 'Plus je me prépare, plus j''ai de chance.', 'Michael Jordan', 'mindset'),
  ('q-0110', 'Le talent fait gagner les matches, mais le travail d''équipe et l''intelligence font gagner des tournois.', 'Michael Jordan', 'leadership'),
  ('q-0113', 'Il n''y a qu''une réponse à la défaite, et c''est la victoire.', 'Winston Churchill', 'mindset'),
  ('q-0115', 'Pour s''améliorer, il faut changer. Donc, pour être parfait, il faut avoir changé souvent.', 'Winston Churchill', 'mindset'),
  ('q-0116', 'Celui qui déplace la montagne, c''est celui qui commence à enlever les petites pierres.', 'Confucius', 'mindset'),
  ('q-0117', 'Celui qui ne progresse pas chaque jour, recule chaque jour.', 'Confucius', 'mindset'),
  ('q-0118', 'Un homme est grand non pas parce qu''il n''a pas échoué ; un homme est grand parce que l''échec ne l''a pas arrêté.', 'Confucius', 'mindset'),
  ('q-0120', 'Ne vous souciez pas de n''être pas remarqué ; cherchez plutôt à faire quelque chose de remarquable.', 'Confucius', 'mindset'),
  ('q-0121', 'Exige beaucoup de toi-même et attends peu des autres.', 'Confucius', 'mindset'),
  ('q-0122', 'Dans les affaires, les grandes choses ne sont jamais faites par une seule personne.', 'Steve Jobs', 'leadership'),
  ('q-0123', 'Les gens qui sont assez fous pour penser qu''ils peuvent changer le monde sont ceux qui le font.', 'Steve Jobs', 'mindset'),
  ('q-0124', 'La simplicité est la sophistication ultime.', 'Steve Jobs', 'mindset'),
  ('q-0125', 'Je suis convaincu que la moitié qui sépare les entrepreneurs qui réussissent de ceux qui échouent est purement la persévérance.', 'Steve Jobs', 'mindset'),
  ('q-0126', 'Innover, c''est savoir abandonner des milliers de bonnes idées.', 'Steve Jobs', 'mindset'),
  ('q-0127', 'Cela n''a aucun sens d''embaucher des gens intelligents et de leur dire quoi faire.', 'Steve Jobs', 'leadership'),
  ('q-0129', 'Ne quittez jamais les flux de trésorerie des yeux, car c''est le sang de l''entreprise.', 'Richard Branson', 'finance'),
  ('q-0130', 'La complexité est votre ennemie. N''importe quel imbécile peut compliquer quelque chose.', 'Richard Branson', 'mindset'),
  ('q-0131', 'Les opportunités, c''est comme les autobus, il y en a toujours un autre qui arrive.', 'Richard Branson', 'mindset'),
  ('q-0132', 'Si vous vous occupez de votre personnel, ils s''occuperont de vos clients.', 'Richard Branson', 'sales'),
  ('q-0133', 'Vous devez prendre des risques si vous voulez réussir.', 'Richard Branson', 'mindset'),
  ('q-0134', 'Parfois, la décision la plus risquée que vous puissiez prendre est de ne rien faire.', 'Richard Branson', 'mindset'),
  ('q-0135', 'Lancer une entreprise, c''est résoudre des problèmes avec succès.', 'Richard Branson', 'leadership'),
  ('q-0136', 'Réussir en affaires, c''est avant tout créer des liens.', 'Richard Branson', 'sales'),
  ('q-0137', 'Le bonheur est l''ingrédient secret des entreprises prospères.', 'Richard Branson', 'leadership'),
  ('q-0138', 'Ce qu''on obtient en atteignant nos objectifs n''est pas aussi important que ce que l''on devient en les atteignant.', 'Zig Ziglar', 'mindset'),
  ('q-0139', 'La pire décision de toutes est celle que l''on n''a pas prise.', 'Zig Ziglar', 'mindset'),
  ('q-0140', 'La meilleure arme de persuasion que tu possèdes dans ton arsenal est l''intégrité.', 'Zig Ziglar', 'sales'),
  ('q-0141', 'Si l''échec vous apprend quelque chose, vous n''êtes pas vraiment perdant.', 'Zig Ziglar', 'mindset'),
  ('q-0142', 'Gagner n''est pas tout, mais l''effort qu''il faut fournir l''est.', 'Zig Ziglar', 'mindset'),
  ('q-0143', 'Plus vous aidez les gens à obtenir ce qu''ils désirent, plus vous avez de succès.', 'Zig Ziglar', 'sales'),
  ('q-0145', 'Le succès ne s''explique pas. L''échec ne s''excuse pas.', 'Napoleon Hill', 'mindset'),
  ('q-0146', 'Chaque difficulté porte en elle le germe d''un avantage équivalent ou supérieur.', 'Napoleon Hill', 'mindset'),
  ('q-0147', 'Les opportunités apparaissent le plus souvent sous la forme de malchance ou d''échec temporaire.', 'Napoleon Hill', 'mindset'),
  ('q-0148', 'Le monde a l''habitude de faire de la place à l''homme dont les paroles et les actions montrent qu''il sait où il va.', 'Napoleon Hill', 'mindset'),
  ('q-0151', 'S''il y a un secret à l''efficacité, c''est la concentration.', 'Peter Drucker', 'mindset'),
  ('q-0152', 'Le temps est le capital le plus rare, et si on ne sait pas le gérer, alors on ne peut rien gérer d''autre.', 'Peter Drucker', 'leadership'),
  ('q-0153', 'Le management se résume à deux fonctions : commercialiser et innover.', 'Peter Drucker', 'leadership'),
  ('q-0154', 'On obtient des résultats en exploitant des opportunités, non en résolvant des problèmes.', 'Peter Drucker', 'mindset'),
  ('q-0155', 'Il n''y a pas « un » caractère d''entrepreneur. Mais il faut « du » caractère pour l''être.', 'Peter Drucker', 'mindset'),
  ('q-0156', 'Pour être irremplaçable, il faut être différente.', 'Coco Chanel', 'mindset'),
  ('q-0157', 'La mode se démode, le style jamais.', 'Coco Chanel', 'mindset'),
  ('q-0158', 'Ma vie ne me plaisait pas, alors j''ai créé ma vie.', 'Coco Chanel', 'mindset'),
  ('q-0159', 'La force est construite par les échecs, pas par les réussites.', 'Coco Chanel', 'mindset'),
  ('q-0161', 'Un investissement dans le savoir paie toujours les meilleurs intérêts.', 'Benjamin Franklin', 'finance'),
  ('q-0162', 'Le temps, c''est de l''argent.', 'Benjamin Franklin', 'finance'),
  ('q-0163', 'Le succès est le résidu de la planification.', 'Benjamin Franklin', 'mindset'),
  ('q-0164', 'Si vous ne parvenez pas à planifier, vous prévoyez d''échouer !', 'Benjamin Franklin', 'mindset'),
  ('q-0165', 'Ne remettez pas au lendemain ce que vous pouvez faire le jour même.', 'Benjamin Franklin', 'mindset'),
  ('q-0166', 'La paresse chemine si lentement que la pauvreté la rattrape.', 'Benjamin Franklin', 'finance'),
  ('q-0168', 'Dans 20 ans, vous serez plus déçu par les choses que vous n''avez pas faites que par celles que vous avez faites.', 'H. Jackson Brown Jr.', 'mindset'),
  ('q-0170', 'Chaque fois que vous vous trouvez du côté de la majorité, il est temps de faire une pause et de réfléchir.', 'Mark Twain', 'mindset'),
  ('q-0172', 'Trop de publicité tue la publicité.', 'Jacques Séguéla', 'sales'),
  ('q-0173', 'Tout homme qui meurt riche meurt déshonoré.', 'Andrew Carnegie', 'finance'),
  ('q-0174', 'Aucun homme ne devient riche à moins qu''il enrichisse autrui.', 'Andrew Carnegie', 'finance'),
  ('q-0176', 'Faites votre devoir et un peu plus encore, et l''avenir prendra soin de lui-même.', 'Andrew Carnegie', 'mindset'),
  ('q-0177', 'Concentrez vos énergies, vos pensées et votre capital.', 'Andrew Carnegie', 'finance'),
