  ('q-0179', 'Ce n''est pas parce que les choses sont difficiles que nous n''osons pas, c''est parce que nous n''osons pas qu''elles sont difficiles.', 'Sénèque', 'mindset'),
  ('q-0180', 'Il n''est pas de vent favorable pour celui qui ne sait pas où il va.', 'Sénèque', 'mindset'),
